 if(bog!=null){water=bog.course.water;bodies=bog.racers.Select(r=>r.truck.body).ToArray();replay=null;bounds=new Bounds(new Vector3(0,0,175),new Vector3(115,50,390));}
 else if(log!=null){water=UnityEngine.Object.FindObjectsByType<LWS.TruckFishing.FishingWaterFlow>(FindObjectsInactive.Include).FirstOrDefault()?.transform;bodies=log.fighters.Select(f=>f.truck.body).Concat(new[]{log.log}).ToArray();replay=log.replay;bounds=new Bounds(Vector3.zero,new Vector3(110,40,110));}
