 for(int i=0;i<48;i++){var line=new GameObject("Pooled surface foam ring "+i).AddComponent<LineRenderer>();line.transform.SetParent(session.transform);line.useWorldSpace=false;line.loop=true;line.positionCount=32;for(int j=0;j<32;j++){float a=j*Mathf.PI*2/32;line.SetPosition(j,new Vector3(Mathf.Cos(a),0,Mathf.Sin(a)));}line.startWidth=line.endWidth=.055f;line.sharedMaterial=foam;line.shadowCastingMode=ShadowCastingMode.Off;line.enabled=false;fx.ripples[i]=line;}var sound=AssetDatabase.LoadAssetAtPath<AudioClip>("Assets/TruckFishing/Audio/Large water scoop.wav");for(int i=0;i<4;i++){var a=new GameObject("Pooled positional water sound "+i).AddComponent<AudioSource>();a.transform.SetParent(session.transform);a.clip=sound;a.spatialBlend=0;a.minDistance=3;a.maxDistance=65;a.rolloffMode=AudioRolloffMode.Logarithmic;a.playOnAwake=false;fx.audio[i]=a;fx.filters[i]=a.gameObject.AddComponent<AudioLowPassFilter>();fx.filters[i].cutoffFrequency=22000;}var rendering=session.GetComponent<LWS.TruckBaseJumping.BaseJumpRendering>();if(rendering!=null){var pipeline=(UniversalRenderPipelineAsset)rendering.pipeline;var serialized=new SerializedObject(pipeline);var list=serialized.FindProperty("m_RendererDataList");var renderer=(UniversalRendererData)list.GetArrayElementAtIndex(0).objectReferenceValue;if(!renderer.rendererFeatures.Any(f=>f is BogUnderwaterFeature)){string rendererPath=folder+"/"+session.gameObject.scene.name+" local water renderer.asset";var copy=AssetDatabase.LoadAssetAtPath<UniversalRendererData>(rendererPath);if(copy==null){copy=UnityEngine.Object.Instantiate(renderer);AssetDatabase.CreateAsset(copy,rendererPath);}var feature=ScriptableObject.CreateInstance<BogUnderwaterFeature>();feature.name="Existing Bog camera-local water depth adapter";AssetDatabase.AddObjectToAsset(feature,copy);copy.rendererFeatures.Add(feature);EditorUtility.SetDirty(copy);list.GetArrayElementAtIndex(0).objectReferenceValue=copy;serialized.ApplyModifiedPropertiesWithoutUndo();}pipeline.suppor