 static void RefreshBounds(SportsWaterInteraction fx){if(fx.surface==null)return;var renderers=fx.surface.GetComponentsInChildren<Renderer>();if(renderers.Length==0)return;var bounds=renderers[0].bounds;foreach(var r in renderers)bounds.Encapsulate(r.bounds);fx.waterBounds=new Bounds(bounds.center,new Vector3(bounds.size.x,100,bounds.size.z));foreach(var effect in UnityEngine.Object.FindObjectsByType<LWS.TruckBogSnorkelling.BogCameraEffects>(FindObjectsInactive.Include))if(effect.waterSurface==fx.surface){effect.waterBounds=fx.waterBounds;EditorUtility.SetDirty(effect);}EditorUtility.SetDirty(fx);}

